begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select set_config('request.jwt.claims','{}',true);
insert into auth.users(id) values('6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),('6bbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb');
insert into public.tool_documents(id,user_id,app_id,title,content,schema_version) values
('6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','plate-layout','A','{"version":1,"plate":{"type":"6","title":"original"},"labels":[],"wells":{},"ui":{}}',1),
('6bbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','6bbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','plate-layout','B','{"version":1,"plate":{"type":"6","title":""},"labels":[],"wells":{},"ui":{}}',1);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa","role":"authenticated"}',true);
select is((select count(*)::int from public.list_deleted_tool_documents()),0,'trash initially empty');
select throws_ok($$insert into public.tool_documents(user_id,app_id,title,content,schema_version) values('6bbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','plate-layout','forged','{}',1)$$,'42501',null,'client cannot supply user_id');
select throws_ok($$insert into public.tool_documents(app_id,title,content,schema_version,purged_at) values('plate-layout','forged','{}',1,now())$$,'42501',null,'purged state injection denied');
select is((select count(*)::int from public.restore_tool_document('6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1)),0,'active document cannot be restored');
select is((select count(*)::int from public.purge_tool_document('6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1)),0,'active document cannot be purged');
select is((select count(*)::int from public.delete_tool_document('6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1)),1,'soft delete succeeds');
select is((select count(*)::int from public.tool_documents),0,'deleted body hidden from normal reads');
select is((select count(*)::int from public.list_deleted_tool_documents()),1,'owner can list trash');
select is((select title from public.list_deleted_tool_documents()),'A','trash metadata preserved');
select is((select count(*)::int from public.restore_tool_document('6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1)),0,'stale restore rejected');
select throws_ok($$select public.restore_tool_document('6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',null)$$,'22023',null,'null restore revision rejected');
select throws_ok($$select public.purge_tool_document('6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',0)$$,'22023',null,'zero purge revision rejected');
select throws_ok($$select public.purge_tool_document('6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',-1)$$,'22023',null,'negative purge revision rejected');
select set_config('request.jwt.claims','{"sub":"6bbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb","role":"authenticated"}',true);
select is((select count(*)::int from public.list_deleted_tool_documents()),0,'B cannot list A trash');
select is((select count(*)::int from public.restore_tool_document('6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',2)),0,'B cannot restore A');
select is((select count(*)::int from public.purge_tool_document('6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',2)),0,'B cannot purge A');
select set_config('request.jwt.claims','{"sub":"6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa","role":"authenticated"}',true);
select is((select revision::int from public.restore_tool_document('6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',2)),3,'restore increments revision');
select is((select content->'plate'->>'title' from public.tool_documents),'original','restore preserves content');
select is((select count(*)::int from public.save_tool_document('6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1,'stale','{}',1)),0,'pre-delete save stays stale after restore');
select is((select count(*)::int from public.delete_tool_document('6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',3)),1,'restored document can be deleted');
select is((select count(*)::int from public.purge_tool_document('6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',2)),0,'stale purge rejected');
select is((select count(*)::int from public.purge_tool_document('6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',4)),1,'versioned purge succeeds');
select is((select count(*)::int from public.list_deleted_tool_documents()),0,'purged document leaves trash');
select is((select count(*)::int from public.restore_tool_document('6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',5)),0,'purged document cannot be restored');
select is((select count(*)::int from public.save_tool_document('6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',5,'revive','{}',1)),0,'purged document cannot be saved');
select throws_ok($$insert into public.tool_documents(id,app_id,title,content,schema_version) values('6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','plate-layout','late','{"version":1,"plate":{"type":"6","title":""},"labels":[],"wells":{},"ui":{}}',1)$$,'23505',null,'late insert cannot reuse purged ID');
select throws_ok($$update public.tool_documents set purged_at=null$$,'42501',null,'direct purge bypass denied');
select throws_ok($$delete from public.tool_documents$$,'42501',null,'direct physical deletion denied');
select set_config('request.jwt.claims','{"role":"authenticated"}',true);
select throws_ok('select * from public.list_deleted_tool_documents()','42501',null,'missing identity cannot list trash');
select throws_ok($$select public.restore_tool_document('6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',5)$$,'42501',null,'missing identity cannot restore');
reset role;
set local role anon;
select throws_ok('select * from public.list_deleted_tool_documents()','42501',null,'anonymous trash denied');
select throws_ok($$select public.purge_tool_document('6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',5)$$,'42501',null,'anonymous purge denied');
reset role;
select set_config('request.jwt.claims','{}',true);
select is((select content from public.tool_documents where id='6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),'{}'::jsonb,'purged body actually removed');
select is((select title from public.tool_documents where id='6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),'[permanently deleted]','purged title actually removed');
select is((select count(*)::int from public.tool_documents where id='6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa' and purged_at is not null and deleted_at is not null),1,'ID tombstone retained');
select ok(not exists(select 1 from pg_proc p where p.proname in ('list_deleted_tool_documents','restore_tool_document','purge_tool_document') and (not p.prosecdef or pg_get_userbyid(p.proowner)<>'postgres' or not coalesce('search_path=""'=any(p.proconfig),false) or has_function_privilege('anon',p.oid,'execute'))),'RPC owners, definer settings and effective anon privileges');
insert into public.tool_documents(user_id,app_id,title,content,schema_version)
select '6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','plate-layout','quota-'||n,'{"version":1,"plate":{"type":"6","title":""},"labels":[],"wells":{},"ui":{}}',1 from generate_series(1,999)n;
select is((select count(*)::int from public.tool_documents where user_id='6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),1000,'purged IDs retain bounded quota usage');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa","role":"authenticated"}',true);
select throws_ok($$insert into public.tool_documents(app_id,title,content,schema_version) values('plate-layout','overflow','{"version":1,"plate":{"type":"6","title":""},"labels":[],"wells":{},"ui":{}}',1)$$,'54000',null,'purging cannot accumulate unbounded unmetered rows');
select throws_ok($$insert into public.tool_documents(id,app_id,title,content,schema_version) values('6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','plate-layout','late','{"version":1,"plate":{"type":"6","title":""},"labels":[],"wells":{},"ui":{}}',1)$$,'23505',null,'purged duplicate at quota limit still returns unique violation');
reset role;
select * from finish();
rollback;
